Translate("deDE", "wailing-caverns", {
	title = "Die Höhlen des Wehklagens",
	aliases = { "Höhlen des Wehklagens" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Höhlen des Wehklagens sind ein Labyrinth aus Höhlen unter dem Herzen von {link:the-barrens}Das Brachland{/link}. Ihr Eingang öffnet sich in einem felsigen Hügel neben der Blühenden Oase, südlich von {link:the-crossroads}Crossroads{/link}. Dampf bricht mit einem langen, klagenden Schrei aus den Spalten ihres Gesteins, und nach diesem Schrei sind sie benannt. Unterirdische Flüsse durchziehen sie meilenweit, und aus ihren verborgenen Quellen steigen die Wasser der neuen Oasen empor. In der Tiefe ist etwas schiefgegangen. Die Tiere der Höhlen sind wild und seltsam geworden, das Wasser trägt eine Verderbnis, die sich über die Ebenen ausbreitet, und die Druiden, die hierherkamen, um das Land zu heilen, dienen nun der Krankheit.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wie alt die Höhlen sind. Bekannt ist, dass der Nachtelfendruide {link:naralex}Naralex{/link} mit einer Schar von Jüngern zu ihnen kam. Er wollte in den {link:emerald-dream}Smaragdgrünen Traum{/link} eintreten und durch dessen Macht und die Quellen der Höhlen das trockene {link:the-barrens}Brachland{/link} wieder zu dem Wald wachsen lassen, der es einst gewesen war. Er legte sich nieder, um zu träumen. Seine Konzentration geriet ins Wanken, und schlangenhafte Visionen schlichen sich in seine Gedanken. Sein Traum wurde zum Albtraum, und er konnte nicht erwachen. Durch seinen schlafenden Geist begann der Albtraum in die wache Welt zu sickern.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[{link:naralex}Naralex{/link} schläft noch immer in den Tiefen der Höhlen und wälzt sich in unruhigem Schlaf. Die meisten seiner Jünger wurden zu den {link:druids-of-the-fang}Druiden des Giftzahns{/link} verzerrt, die die Gestalt von Schlangen tragen und den Schlummer ihres Meisters gegen alle bewachen, die ihn beenden wollen. Ihre vier Anführer, die Giftzahnfürsten, besitzen je einen Edelstein des Traums. Deviatraptoren, Schlangen und Feendrachen sind aus dem Albtraum aufgestiegen und suchen die Tunnel heim, und gestaltlose Ektoplasmen treiben durch die Dunkelheit.

Die Welt darüber hat begonnen, es zu bemerken. Der Taurendruide {link:tonga-runetotem}Tonga Runetotem{/link} verfolgte die Verderbnis der Oasen bis zu den Höhlen, und {link:hamuul-runetotem}Hamuul Runetotem{/link} sah die Druiden des Giftzahns in seinen eigenen Träumen. {link:nara-wildmane}Nara Wildmane{/link} lernte ihre Gesichter kennen und will ihre Edelsteine. Der verlassene Apotheker {link:apothecary-zamah}Apotheker Zamah{/link} sucht die Schlangenflaumblüte, die in den Tiefen wächst. Die Goblins von {link:ratchet}Ratchet{/link} wollen die Essenz der Ektoplasmen für ihre Getränke, und ein Dieb namens Mad Magglish ist mit einer gestohlenen Flasche alten Portweins hineingeflohen. Einige {link:disciple-of-naralex}Jünger des Naralex{/link} sind treu geblieben. Einer wartet in den Höhlen auf jemanden, der stark genug ist, ihm beim Erwecken seines Meisters zu helfen.]=],
		},
		{
			title = "In den Höhlen",
			text = [=[• {b}Der Eingang.{/b} Zwei treue Jünger, Nalpak und Ebru, halten auf dem Hügel über dem Eingang Wache. Die Druidin Falla Sagewind wartet in der Nähe.
• {b}Die Höhlen des Giftzahns.{/b} In den oberen Höhlen befehligen {link:lady-anacondra}Lady Anacondra{/link} und {link:lord-cobrahn}Lord Cobrahn{/link} die Druiden und ihre Schlangen.
• {b}Der Fluss.{/b} Eine alte Schildkröte, {link:kresh}Kresh{/link}, wandert durch den unterirdischen Fluss, unberührt vom Albtraum.
• {b}Die tiefen Gruben.{/b} {link:lord-pythas}Lord Pythas{/link} und {link:lord-serpentis}Lord Serpentis{/link} halten die unteren Kammern. Die Donnerechse {link:skum}Skum{/link} und der {link:the-night-watch}Wächter{/link} {link:verdan-the-everliving}Verdan der Ewiglebende{/link} lauern in den fernen Höhlen.
• {b}Die Kammer des Träumers.{/b} Im Herzen der Höhlen liegt {link:naralex}Naralex{/link} in seinem unruhigen Schlaf. Unter dem trüben Wasser nahe bei ihm wartet etwas.]=],
		},
	},
})

Translate("deDE", "naralex", {
	title = "Naralex",
	subtitle = "Der Träumer der Höhlen",
	found = "Die Kammer des Träumers, tief in den Höhlen des Wehklagens",
	hint = [=[Sucht den Druiden, der im Herzen der Höhlen des Wehklagens schläft.]=],
	allegiance = "Jünger des Naralex · Nachtelfen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Naralex ist ein Nachtelfendruide, der mit einem edlen Ziel in die {link:wailing-caverns}Höhlen des Wehklagens{/link} kam. Er glaubte, durch den {link:emerald-dream}Smaragdgrünen Traum{/link} und die verborgenen Quellen der Höhlen das {link:the-barrens}Brachland{/link} wieder erblühen lassen zu können. Er trat in den Traum ein und kehrte nicht zurück. Seine Vision des Neuwuchses wurde zum Albtraum, und er liegt noch immer in den Tiefen der Höhlen, verloren zwischen Schlaf und Wahnsinn. Der Albtraum strömt aus ihm in die Wasser und die Tiere.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Naralex ist die Quelle der Verderbnis des Brachlands und ihr erstes Opfer. Seine eigenen Jünger sind zu seinen Kerkermeistern geworden. Solange er schläft, brüten die Höhlen Ungeheuer aus, und die Oasen tragen seine Krankheit über die Ebenen. Sein Schicksal ist zugleich eine Warnung an jeden Druiden Azeroths: Der Traum ist nicht so sicher, wie sie glaubten.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führte seine Jünger in die {link:wailing-caverns}Höhlen des Wehklagens{/link}, um das {link:the-barrens}Brachland{/link} zu heilen.
• Er trat in den Smaragdgrünen Traum ein und wurde in einem Albtraum gefangen.
• Durch seine Träume gelangten Deviattiere und Ektoplasmen in die wache Welt.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Wenig ist hier über Naralex' Leben vor den Höhlen geschrieben. Dieser Eintrag verzeichnet nur, was seine Jünger und sein Traum offenbaren.]=],
		},
	},
	chapters = {
		{
			title = "Der Albtraum",
			hint = "Erfahrt von den treuen Jüngern, warum Naralex schläft.",
			text = [=[Die Jünger, die treu blieben, erzählen dieselbe Geschichte. Ihr Meister strebte danach, in den Traum einzutreten und das raue Land grün zu machen. Etwas ging furchtbar schief. Als Naralex tiefer in seinen Albtraum sank, stiegen seltsame Tiere aus der Tiefe unter dem {link:the-barrens}Brachland{/link} in die Höhlen empor, und die Druiden, die ihn liebten, wurden verwandelt.]=],
		},
		{
			title = "Das Erwachen",
			hint = [=[Beschützt den Jünger, während er den Ritus des Erwachens vollzieht.]=],
			text = [=[Als die vier {link:druids-of-the-fang}Giftzahnfürsten{/link} erschlagen waren, ging der letzte treue Jünger zur Kammer seines Meisters voran und griff in den Traum, um ihn zu finden. Albträume erhoben sich, um ihn aufzuhalten: Schlangen, Schleime und schließlich eine ungeheuerliche Kreatur aus dem Wasser. Als sie fiel, rief Naralex, er sei erwacht. Aus dem Leib der Bestie kam ein grüner Splitter, in dem Rauch zu wirbeln schien, ein Bruchstück des Traums, das einen Albtraum zeigte.]=],
		},
	},
	mentions = {
		{ text = "Der leuchtende Splitter" },
		{
			text = [=[In Albträumen, der Splitter nach {link:thunder-bluff}Thunder Bluff{/link} gebracht]=],
		},
		{
			text = [=[In Albträumen, der Splitter nach {link:darnassus}Darnassus{/link} gebracht]=],
		},
	},
	bonds = {
		{ id = "disciple-of-naralex", name = "Jünger des Naralex", note = "sein treuer Schüler" },
		{ id = "lord-serpentis", name = "Lord Serpentis", note = "sein Schüler, nun sein Kerkermeister" },
		{ id = "mutanus-the-devourer", name = "Mutanus der Verschlinger", note = "der Albtraum, der seinen Schlaf bewacht" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "las den Splitter seines Albtraums" },
	},
})

Translate("deDE", "disciple-of-naralex", {
	title = "Jünger des Naralex",
	subtitle = "Der letzte treue Jünger",
	found = "Der Eingang der Höhlen des Wehklagens",
	hint = [=[Sprecht mit dem Jünger, der am Eingang der Höhlen des Wehklagens wartet.]=],
	allegiance = "Jünger des Naralex · Tauren",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Jünger des Naralex ist ein Taurendruide, einer der wenigen Anhänger des {link:naralex}Naralex{/link}, die der Albtraum nicht verzerrt hat. Er wartet gleich hinter dem Eingang der {link:wailing-caverns}Höhlen des Wehklagens{/link}. Sein Meister schlafe wieder, sagt er, und reptilienhafte Bestien sickerten aus seinen Träumen ins Land. Naralex müsse aus seinem Albtraum geweckt werden oder er sei für immer verloren, und ein großes Übel würde entfesselt. Doch der Jünger kann den Ritus des Erwachens nicht vollziehen, solange seine verderbten Brüder leben. Zuerst müssen die vier {link:druids-of-the-fang}Giftzahnfürsten{/link} sterben.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Der Jünger ist die einzige Hoffnung des Träumers. Er kennt den Ritus, der {link:naralex}Naralex{/link} zurückrufen kann, und er hat trotz allem, was aus den Höhlen geworden ist, die Treue gehalten. Er spricht mit Trauer von ihnen: einst ein Tempel der Verheißung für das {link:the-barrens}Brachland{/link}, nun Hallen des Albtraums.]=],
		},
		{
			title = "Taten",
			text = [=[• Er segnet jene, die die Höhlen betreten wollen, mit dem Mal der Wildnis.
• Er verlangt den Tod der vier {link:druids-of-the-fang}Giftzahnfürsten{/link}.
• Er bannt die Geister der erschlagenen Giftzahnfürsten in einem Feuerkreis.
• Er greift in den Smaragdgrünen Traum, um seinen Meister zu wecken.]=],
		},
	},
	chapters = {
		{
			title = "Der Ritus des Erwachens",
			hint = [=[Erschlagt die Giftzahnfürsten und beschützt dann den Jünger auf seinem Weg zu Naralex.]=],
			text = [=[Als die {link:druids-of-the-fang}Giftzahnfürsten{/link} tot waren, erklärte der Jünger, dass nicht alle Hoffnung verloren sei, doch den Ritus könne er nicht allein vollenden. Er ging durch die Höhlen voran und reinigte sie unterwegs, während die Albträume seines Meisters Vipern und Schlimmeres gegen ihn sandten. An {link:naralex}Naralex{/link}' Seite tauchte er in den Traum ein. Das Ritual war lang, und die Angriffe wurden heftiger, bis der Träumer endlich erwachte.]=],
		},
	},
	mentions = {
		{ text = "Deviathäute, erbeten von seinem Mitjünger Nalpak" },
		{ text = "Deviatausrottung, erbeten von seiner Mitjüngerin Ebru" },
	},
	bonds = {
		{ id = "naralex", name = "Naralex", note = "sein Meister" },
		{ id = "lord-serpentis", name = "Lord Serpentis", note = "ein Bruder, der fiel" },
	},
})

