		{
			title = "Zusammenfassung",
			text = [=[Skum ist eine große Donnerechse des Brachlands. Es heißt, er sei in die Höhlen hinabgestiegen, um dem rauen Land darüber zu entkommen, auf der Suche nach Wasser und Schatten. Wie so viele Kreaturen der Höhlen entkam er der Verderbnis nicht. Dunkle Energien pulsieren nun in seinen Adern, und er ist zu einer gnadenlosen Bestie geworden, die nicht mehr zu retten ist.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Skum ist der Beweis, dass der Albtraum selbst die Tiere ergreift, die nur Zuflucht suchen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er lauert in den fernen Höhlen, wohin sich nur wenige wagen.]=],
		},
	},
})

Translate("deDE", "kresh", {
	title = "Kresh",
	subtitle = "Die unberührte Schildkröte",
	found = "Der unterirdische Fluss der Höhlen des Wehklagens",
	hint = [=[Sucht nach der alten Schildkröte, die im unterirdischen Fluss schwimmt.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kresh ist eine uralte Schildkröte, die im unterirdischen Fluss der {link:wailing-caverns}Höhlen des Wehklagens{/link} schwimmt. Seltsamerweise hat der Albtraum ihn nicht berührt. Während sich alles um ihn herum verzerrt und erkrankt, lebt er weiter, wie er es immer tat, ruhig und ohne Acht auf das Böse in der Dunkelheit. Viele haben versucht, seinen großen Panzer zu erbeuten. Er hat ihn behalten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Kresh ist die einzige Kreatur der Höhlen, die der Albtraum nicht verändern konnte.]=],
		},
		{ title = "Taten", text = "• Er wandert durch den Fluss, unberührt von der Verderbnis." },
	},
})

Translate("deDE", "druids-of-the-fang", {
	title = "Druiden des Giftzahns",
	aliases = { "Druide des Giftzahns", "Giftzahnfürsten", "Giftzahnfürst" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Druiden des Giftzahns sind die verderbten Anhänger des {link:naralex}Naralex{/link}. Sie kamen als Orden edler Druiden in die {link:wailing-caverns}Höhlen des Wehklagens{/link}, um das {link:the-barrens}Brachland{/link} zu heilen. Als der Traum ihres Meisters zum Albtraum wurde, fielen die meisten von ihnen mit ihm. Nun tragen sie geschuppte Gesichter und Schlangengestalten, und sie trachten danach, das Land nach dem Bild ihrer eigenen verzerrten Träume neu zu formen.]=],
		},
		{
			title = "Der Orden",
			text = [=[Vier Anführer befehligen sie, die Giftzahnfürsten: {link:lady-anacondra}Lady Anacondra{/link}, {link:lord-cobrahn}Lord Cobrahn{/link}, {link:lord-pythas}Lord Pythas{/link} und ihr Oberhaupt, {link:lord-serpentis}Lord Serpentis{/link}. Jeder von ihnen besitzt einen Edelstein des Traums. Unter ihnen halten Druiden des Giftzahns Deviatschlangen und -raptoren als ihre Tiere, und einige wandeln auf den Ebenen darüber. Einer von ihnen, Boahn, wurde nahe dem Hügel der Höhlen gesehen. Die wenigen Jünger, die ihren Verstand bewahrten, unter ihnen Nalpak, Ebru und der Jünger, der drinnen wartet, arbeiten nun gegen ihre gefallenen Brüder.]=],
		},
		{
			title = "Was die Druiden sahen",
			text = [=[{link:hamuul-runetotem}Hamuul Runetotem{/link} trat in das Träumen ein, um zu erfahren, was das {link:the-barrens}Brachland{/link} vergiftete. Er sah einen Kult von Druiden, deren Ziele einst edel gewesen waren und die ihren Weg verloren hatten, im Dienst der Verderbnis, die durch das Land sickerte. Er war alt und konnte nicht lange bleiben. {link:nara-wildmane}Nara Wildmane{/link} blieb und sah ihre Gesichter. Sie sagt, sie verfolgten sie noch immer.]=],
		},
	},
})
